#include <cstddef>
#include <cstdint>
#include <cstring>
static std::size_t base(std::size_t d,std::size_t i){return 2+d+i*(d+2);}
static bool valid_tree(const std::int64_t*v,std::size_t d,std::size_t n,int i,bool*seen,std::size_t&count){if(i<0)return true;if(static_cast<std::size_t>(i)>=n||seen[i])return false;seen[i]=true;count++;auto b=base(d,i);auto l=v[b+d],r=v[b+d+1];if(l>=0&&l==r)return false;return valid_tree(v,d,n,static_cast<int>(l),seen,count)&&valid_tree(v,d,n,static_cast<int>(r),seen,count);}
static void search(const std::int64_t*v,std::size_t d,int i,std::size_t depth,const std::int64_t*q,std::int64_t*best,std::int64_t&bestd,std::int64_t&vis){if(i<0)return;vis++;auto b=base(d,i);std::int64_t dist=0;for(std::size_t k=0;k<d;k++){auto z=q[k]-v[b+k];dist+=z*z;}if(dist<bestd){bestd=dist;for(std::size_t k=0;k<d;k++)best[k]=v[b+k];}auto axis=depth%d;auto l=v[b+d],r=v[b+d+1];int near,far;if(q[axis]<=v[b+axis]){near=(int)l;far=(int)r;}else{near=(int)r;far=(int)l;}search(v,d,near,depth+1,q,best,bestd,vis);auto split=q[axis]-v[b+axis];if(split*split<bestd)search(v,d,far,depth+1,q,best,bestd,vis);}
static void put_i64(std::uint8_t*out,std::size_t o,std::int64_t x){std::uint64_t b;std::memcpy(&b,&x,8);for(std::size_t k=0;k<8;k++)out[o+k]=(std::uint8_t)(b>>(8*k));}
extern "C" std::int64_t nearest_neighbour_search(const std::int64_t*v,std::size_t n,std::uint8_t*out,std::size_t cap){if(!v||n<5)return -1;auto d0=v[0],n0=v[1];if((d0!=2&&d0!=3)||n0<1||n0>15)return -1;auto d=(std::size_t)d0,count=(std::size_t)n0;if(n!=2+d+count*(d+2))return -1;std::int64_t q[3]={},best[3]={};for(std::size_t k=0;k<d;k++){q[k]=v[2+k];if(q[k]<-1000||q[k]>1000)return -1;}for(std::size_t i=0;i<count;i++){auto b=base(d,i);for(std::size_t k=0;k<d;k++)if(v[b+k]<-1000||v[b+k]>1000)return -1;auto l=v[b+d],r=v[b+d+1];if(l < -1||l>=n0||r < -1||r>=n0)return -1;}bool seen[15]={};std::size_t reached=0;if(!valid_tree(v,d,count,0,seen,reached)||reached!=count)return -1;std::int64_t bestd=INT64_MAX,vis=0;search(v,d,0,0,q,best,bestd,vis);if(!out||cap<48)return -2;std::int64_t result[6]={(std::int64_t)d,best[0],best[1],d==3?best[2]:0,bestd,vis};for(std::size_t k=0;k<6;k++)put_i64(out,k*8,result[k]);return 48;}
